import { useState } from 'react';

type ContactData = {
  fullName: string;
  email: string;
  phone: string;
};

type AddressData = {
  street: string;
  city: string;
  zip: string;
};

type RegistrationData = ContactData & AddressData;

interface RegistrationFormProps {
  onSubmit: (data: RegistrationData) => void;
}

const STEPS = ['Контакты', 'Адрес', 'Проверка'] as const;

const INITIAL_DATA: RegistrationData = {
  fullName: '',
  email: '',
  phone: '',
  street: '',
  city: '',
  zip: '',
};

export default function RegistrationForm({ onSubmit }: RegistrationFormProps) {
  const [stepIndex, setStepIndex] = useState(0);
  const [data, setData] = useState<RegistrationData>(INITIAL_DATA);

  const isLastStep = stepIndex === STEPS.length - 1;
  const isFirstStep = stepIndex === 0;

  const canGoNext =
    stepIndex === 0
      ? data.fullName.trim() !== '' && data.email.trim() !== ''
      : stepIndex === 1
      ? data.street.trim() !== '' && data.city.trim() !== '' && data.zip.trim() !== ''
      : true;

  const updateField = (field: keyof RegistrationData) => (
    event: React.ChangeEvent<HTMLInputElement>
  ) => {
    setData((prev) => ({ ...prev, [field]: event.target.value }));
  };

  const goBack = () => {
    setStepIndex((prev) => Math.max(0, prev - 1));
  };

  const goNext = () => {
    setStepIndex((prev) => Math.min(STEPS.length - 1, prev + 1));
  };

  const handleSubmit = () => {
    onSubmit(data);
  };

  return (
    <section
      className="jx-card"
      style={{ maxWidth: 480, padding: 'var(--jx-space-6)' }}
    >
      <ol
        className="jx-steps"
        aria-label="Шаги регистрации"
        style={{
          display: 'flex',
          gap: 'var(--jx-space-2)',
          marginBottom: 'var(--jx-space-6)',
          listStyle: 'none',
          padding: 0,
        }}
      >
        {STEPS.map((label, index) => {
          const isActive = index === stepIndex;
          const isDone = index < stepIndex;
          const stateClass = isActive
            ? 'jx-steps__item--active'
            : isDone
            ? 'jx-steps__item--done'
            : 'jx-steps__item--pending';

          return (
            <li
              key={label}
              className={`jx-steps__item ${stateClass}`}
              aria-current={isActive ? 'step' : undefined}
              style={{ flex: 1 }}
            >
              <span className="jx-steps__index">{index + 1}</span>
              <span className="jx-steps__label">{label}</span>
            </li>
          );
        })}
      </ol>

      <form
        onSubmit={(event) => {
          event.preventDefault();
          if (isLastStep) {
            handleSubmit();
          } else if (canGoNext) {
            goNext();
          }
        }}
      >
        {stepIndex === 0 && (
          <fieldset
            className="jx-fieldset"
            style={{ display: 'flex', flexDirection: 'column', gap: 'var(--jx-space-4)' }}
          >
            <legend className="jx-legend">Контакты</legend>

            <label className="jx-field">
              <span className="jx-label">Полное имя</span>
              <input
                className="jx-input"
                type="text"
                value={data.fullName}
                onChange={updateField('fullName')}
                required
              />
            </label>

            <label className="jx-field">
              <span className="jx-label">Email</span>
              <input
                className="jx-input"
                type="email"
                value={data.email}
                onChange={updateField('email')}
                required
              />
            </label>

            <label className="jx-field">
              <span className="jx-label">Телефон</span>
              <input
                className="jx-input"
                type="tel"
                value={data.phone}
                onChange={updateField('phone')}
              />
            </label>
          </fieldset>
        )}

        {stepIndex === 1 && (
          <fieldset
            className="jx-fieldset"
            style={{ display: 'flex', flexDirection: 'column', gap: 'var(--jx-space-4)' }}
          >
            <legend className="jx-legend">Адрес</legend>

            <label className="jx-field">
              <span className="jx-label">Улица и дом</span>
              <input
                className="jx-input"
                type="text"
                value={data.street}
                onChange={updateField('street')}
                required
              />
            </label>

            <label className="jx-field">
              <span className="jx-label">Город</span>
              <input
                className="jx-input"
                type="text"
                value={data.city}
                onChange={updateField('city')}
                required
              />
            </label>

            <label className="jx-field">
              <span className="jx-label">Индекс</span>
              <input
                className="jx-input"
                type="text"
                value={data.zip}
                onChange={updateField('zip')}
                required
              />
            </label>
          </fieldset>
        )}

        {stepIndex === 2 && (
          <div
            className="jx-summary"
            style={{ display: 'flex', flexDirection: 'column', gap: 'var(--jx-space-3)' }}
          >
            <h3 className="jx-summary__title">Проверка данных</h3>

            <dl className="jx-summary__list">
              <div className="jx-summary__row">
                <dt className="jx-summary__key">Имя</dt>
                <dd className="jx-summary__value">{data.fullName}</dd>
              </div>
              <div className="jx-summary__row">
                <dt className="jx-summary__key">Email</dt>
                <dd className="jx-summary__value">{data.email}</dd>
              </div>
              <div className="jx-summary__row">
                <dt className="jx-summary__key">Телефон</dt>
                <dd className="jx-summary__value">{data.phone || '—'}</dd>
              </div>
              <div className="jx-summary__row">
                <dt className="jx-summary__key">Адрес</dt>
                <dd className="jx-summary__value">{data.street}</dd>
              </div>
              <div className="jx-summary__row">
                <dt className="jx-summary__key">Город</dt>
                <dd className="jx-summary__value">{data.city}</dd>
              </div>
              <div className="jx-summary__row">
                <dt className="jx-summary__key">Индекс</dt>
                <dd className="jx-summary__value">{data.zip}</dd>
              </div>
            </dl>
          </div>
        )}

        <div
          className="jx-form-actions"
          style={{
            display: 'flex',
            justifyContent: 'space-between',
            marginTop: 'var(--jx-space-6)',
            gap: 'var(--jx-space-3)',
          }}
        >
          <button
            type="button"
            className="jx-button jx-button--ghost"
            onClick={goBack}
            disabled={isFirstStep}
          >
            Назад
          </button>

          {isLastStep ? (
            <button type="submit" className="jx-button jx-button--primary">
              Отправить
            </button>
          ) : (
            <button
              type="submit"
              className="jx-button jx-button--primary"
              disabled={!canGoNext}
            >
              Дальше
            </button>
          )}
        </div>
      </form>
    </section>
  );
}

